<script module lang="ts">
/**
 * The full view of one entity (`design/archetypes/detail-page.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/detail-page.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { type Snippet } from 'svelte'

import { SlotOutlet, SlotScope, joinSlot } from '@polymorph/svelte'
import styles from '@polymorph/recipes/archetypes/detail-page.module.css'
import Button from '../controls/Button.svelte'

export interface DetailPageProps {
  /**
   * Header actions under PageHeader's law: at most one solid button, and destructive actions in
   * a Menu.
   */
  actions?: Snippet
  /**
   * Stat and meta Cards, and when omitted the body is one column.
   */
  aside?: Snippet
  backLabel: string
  /**
   * The plain body, omitted when `tabs` provides it.
   */
  children?: Snippet
  /**
   * The identity row, such as Badges, an Avatar and timestamps.
   */
  meta?: Snippet
  onBack?: () => void
  /**
   * Keeps the aside in view while the main column scrolls, at the widths where it is beside the
   * main column. It is never taller than the visible box and scrolls inside itself when it is
   * longer. Default `false`: the aside scrolls with the page.
   */
  stickyAside?: boolean
  /**
   * A full-width `Tabs` as the tabbed body. Use either `tabs` or `children`, not both. A Tabs
   * renders its own panels, so a page with both would show the tab content and then the children
   * below it.
   */
  tabs?: Snippet
  /**
   * The entity's name, rendered as the page's `<h1>`.
   */
  title: string
  /**
   * An InlineEdit of the entity's name, drawn beside the `<h1>` as PageHeader draws one, with
   * `title` as its `value` and `size="lg"`. The page hands it `valueHidden`. The app gives it
   * its label, its handlers and, for a save that waits for a server, `editing`, `pending` and
   * `error`.
   */
  titleEdit?: Snippet
}
</script>

<script lang="ts">
let {
  actions,
  aside,
  backLabel,
  children,
  meta,
  onBack,
  stickyAside = false,
  tabs,
  title,
  titleEdit,
}: DetailPageProps = $props()
const joined = joinSlot(undefined, () => ({}))
const slots = {
  get actions() {
    return actions
  },
  get aside() {
    return aside
  },
  get default() {
    return children
  },
  get meta() {
    return meta
  },
  get tabs() {
    return tabs
  },
  get titleEdit() {
    return titleEdit
  },
}
const titleEditScope: SlotScope = new SlotScope({
  pass: (): Record<string, unknown> => ({ valueHidden: true }),
})
</script>

{@render joined.start?.()
}{#if joined.shown
  }<div class={styles.page} data-member="detail-page"
    ><div class={styles.back}
      ><Button
        variant="ghost"
        tone="neutral"
        size="sm"
        icon="back"
        label={backLabel}
        onClick={() => { onBack?.() }}
    /></div
    ><div class={styles.header}
      ><div class={styles.identity}
        >{#if slots.titleEdit
          }<div class={styles.titleRow}
            ><h1 class={styles.title}>{title}</h1
            ><div class={styles.titleEdit}
              ><SlotOutlet scope={titleEditScope} snippet={titleEdit}
            /></div
          ></div
        >{:else
          }<h1 class={styles.title}>{title}</h1
        >{/if
        }{#if slots.meta}<div class={styles.meta}>{@render meta?.()}</div>{/if
      }</div
      >{#if slots.actions}<div class={styles.actions}>{@render actions?.()}</div>{/if
    }</div
    >{@render tabs?.()
    }{#if slots.default || slots.aside
      }<div
        class={styles.body}
        data-aside={(slots.aside) ? '' : undefined}
        data-sticky-aside={(slots.aside && stickyAside) ? '' : undefined}
        ><div class={styles.main}>{@render children?.()}</div
        >{#if slots.aside}<div class={styles.aside}>{@render aside?.()}</div>{/if
      }</div
    >{/if
  }</div
>{/if
}{@render joined.end?.()}
